package run.ikaros.photo; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono; import run.ikaros.common.IfMatchVersion;
@RestController @RequestMapping("/api/v2/photos/{photoId}/metadata") public class PhotoMetadataController{private final PhotoMetadataService service;public PhotoMetadataController(PhotoMetadataService s){service=s;}@PutMapping public Mono<ResponseEntity<PhotoView>> update(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID photoId,@RequestHeader(value="If-Match",required=false)String ifMatch,@Valid@RequestBody UpdatePhotoMetadataRequest r){return service.update(o,photoId,r,IfMatchVersion.parse(ifMatch)).map(view->ResponseEntity.ok().eTag(IfMatchVersion.etag(view.version())).body(view));}@GetMapping public Mono<ResponseEntity<PhotoView>> get(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID photoId){return service.get(o,photoId).map(view->ResponseEntity.ok().eTag(IfMatchVersion.etag(view.version())).body(view));}}
